create function public.test_classic_commission_view(p_id uuid) returns jsonb language sql security definer as $$ select public.partner_network_commission_view(p_id) $$;
create function public.test_classic_reward_view(p_id uuid) returns jsonb language sql security definer as $$ select public.partner_network_reward_view(p_id) $$;
create function public.test_classic_reward_month(p_id uuid,p_month date) returns jsonb language sql security definer as $$ select public.partner_network_reward_month(p_id,p_month) $$;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.test_assert((select count(*) from public.partner_network_classic_agreements)=0,'migration does not alter existing agreements');
select public.test_assert((select count(*) from public.partner_network_rewards)=0,'migration does not invent rewards');
select public.test_assert((select status='paid' and paid_amount=82500 from public.partner_network_commissions where order_id='test-o1'),'legacy paid record unchanged');
select set_config('test.legacy_rate',(select default_rate_percent::text from public.partner_network_partners where id=current_setting('test.partner_a')::uuid),false);
select public.partner_network_apply_classic(current_setting('test.partner_a')::uuid,'{"expected_version":0,"reason":"Manager explicitly agreed confirmed Classic terms for future attributed orders"}');
select public.test_assert((select default_rate_percent=current_setting('test.legacy_rate')::numeric from public.partner_network_partners where id=current_setting('test.partner_a')::uuid),'Classic never overwrites legacy rate fields');
select public.test_error(format('select public.partner_network_apply_classic(%L,''{"expected_version":0,"reason":"Concurrent outdated manager form must not overwrite terms"}'')',current_setting('test.partner_a')),'classic_agreement_changed');
reset role;
-- New attributed orders only; synthetic data never leaves this disposable database.
insert into public.orders(id,ts,type,status,customer_name,contact,address,partner_account_id,lines) values
 ('classic-1',now()+interval '1 minute','wholesale','confirmed','Cafe A','0902000001','Hà Nội','test-client','[]'),
 ('classic-2',now()+interval '2 minutes','wholesale','confirmed','Cafe A','0902000001','Hà Nội','test-client','[]'),
 ('classic-3',now()+interval '3 minutes','wholesale','confirmed','Cafe A','0902000001','Hà Nội','test-client','[]');
insert into public.receivables values('classic-r1','classic-1',1000000,1000000,'paid'),('classic-r2','classic-2',1000000,500000,'partial'),('classic-r3','classic-3',1000000,1000000,'paid');
insert into public.receivable_payments(id,receivable_id,amount) values('classic-p1','classic-r1',1000000),('classic-p2','classic-r2',500000),('classic-p3','classic-r3',1000000);
set role authenticated;
select public.partner_network_reconcile('classic-1','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"review_note":"Costs not yet confirmed; never assume zero cost"}');
select public.test_assert((select commission_basis='profit' and calculated_amount is null and rate_percent=1 from public.partner_network_commissions where order_id='classic-1'),'first Classic order 1 percent unknown profit remains unknown');
select public.test_error(format('select public.partner_network_commission_action(%L,''approve'',''{}'')',(select id from public.partner_network_commissions where order_id='classic-1')),'profit_review_required');
select public.partner_network_reconcile('classic-1','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Actual cost confirmed for first Classic order"}');
select public.test_assert((select rate_percent=1 and calculated_amount=5000 from public.partner_network_commissions where order_id='classic-1'),'Classic percentage is of profit before commission, not revenue');
reset role;
update public.orders set status='completed',delivered_at=now() where id='classic-1';
set role authenticated;
select public.partner_network_reconcile('classic-2','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":100000,"minimum_retained_profit":100000,"review_note":"Second order only partially collected"}');
select public.test_assert((select rate_percent=1 from public.partner_network_commissions where order_id='classic-2'),'second order stays 1 percent');
reset role;
update public.orders set status='completed',delivered_at=now() where id='classic-2';
set role authenticated;
select public.partner_network_reconcile('classic-3','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Third order must wait for two qualifying preceding purchases"}');
select public.test_assert((select rate_percent=1 from public.partner_network_commissions where order_id='classic-3'),'partial preceding payment cannot qualify for repeat tier');
reset role;
insert into public.receivable_payments(id,receivable_id,amount) values('classic-p2b','classic-r2',500000);
update public.receivables set paid=1000000,status='paid' where id='classic-r2';
set role authenticated;
select public.test_assert((select (public.test_classic_commission_view(id)->>'stale')::boolean from public.partner_network_commissions where order_id='classic-3'),'new qualifying payment invalidates stale rate');
select public.partner_network_reconcile('classic-3','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Two completed paid purchases now qualify repeat rate"}');
select public.test_assert((select rate_percent=2 and calculated_amount=10000 from public.partner_network_commissions where order_id='classic-3'),'third qualifying same-client purchase gets 2 percent');
select public.test_error($q$select public.partner_network_reconcile('classic-3','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"review_note":"Attempt to change classic to revenue","commission_basis":"revenue"}')$q$,'classic_requires_profit_basis');
select public.partner_network_reconcile('classic-1','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":1,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Customer refund removes this order from qualifying repeat count"}');
select public.test_assert((select (public.test_classic_commission_view(id)->>'stale')::boolean from public.partner_network_commissions where order_id='classic-3'),'refund invalidates pending repeat entitlement');
select public.partner_network_reconcile('classic-1','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Refund correction verified"}');
select public.partner_network_reconcile('classic-3','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Repeat entitlement reviewed before settlement"}');
select public.partner_network_commission_action((select id from public.partner_network_commissions where order_id='classic-3'),'approve','{}');
select public.partner_network_commission_action((select id from public.partner_network_commissions where order_id='classic-3'),'pay',jsonb_build_object('amount',10000,'reference','synthetic-classic-transfer','paid_at',now()));
select set_config('test.classic_paid',(select to_jsonb(c)::text from public.partner_network_commissions c where order_id='classic-3'),false);
-- No monthly amount exists until a manager deliberately configures a rule.
select public.test_assert(jsonb_array_length(public.partner_network_rewards_snapshot()->'monthly_rules')=0,'monthly bonus starts disabled/unconfigured');
select public.partner_network_reward_rule(current_setting('test.partner_a')::uuid,jsonb_build_object('effective_month',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date,'thresholds','[{"minimum_orders":1,"amount":50000},{"minimum_orders":2,"amount":150000}]'::jsonb,'enabled',true,'reason','Explicit illustrative test-only bonus tiers approved by manager','expected_version',0));
select public.test_assert((public.test_classic_reward_month(current_setting('test.partner_a')::uuid,date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date)->>'count')::integer=2,'monthly count has only completed fully collected attributed orders');
select set_config('test.monthly_reward',(public.partner_network_reward_create(current_setting('test.partner_a')::uuid,jsonb_build_object('kind','monthly','month',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date,'reason','Review counted completed orders for the current month'))->>'id'),false);
select public.test_assert((select amount=150000 and qualifying_orders=2 from public.partner_network_rewards where id=current_setting('test.monthly_reward')::uuid),'highest monthly threshold only; bonuses do not stack');
select public.test_error(format('select public.partner_network_reward_action(%L,''approve'',''{}'')',current_setting('test.monthly_reward')),'reward_month_not_closed');
select public.test_error(format('select public.partner_network_reward_rule(%L,%L)',current_setting('test.partner_a'),jsonb_build_object('effective_month',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date,'thresholds','[]'::jsonb,'enabled',true,'reason','An empty active tier table is not a promise','expected_version',1)::text),'invalid_reward_rule');
select public.partner_network_reconcile('classic-2','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":1000000,"internal_cost_total":100000,"minimum_retained_profit":100000,"review_note":"Full refund after bonus review must invalidate pending bonus"}');
select public.test_assert((public.test_classic_reward_view(current_setting('test.monthly_reward')::uuid)->>'stale')::boolean,'refund invalidates unpaid monthly bonus');
select public.test_assert((select to_jsonb(c)=current_setting('test.classic_paid')::jsonb from public.partner_network_commissions c where order_id='classic-3'),'later refund never changes recorded paid commission');
select public.test_assert((select (public.test_classic_commission_view(id)->>'entitlement_review_required')::boolean from public.partner_network_commissions where order_id='classic-3'),'paid repeat entitlement change requires human review');
-- Personal rewards are explicit money, independent of percentage or monthly multipliers.
select set_config('test.personal_reward',(public.partner_network_reward_create(current_setting('test.partner_a')::uuid,jsonb_build_object('kind','personal','month',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date,'amount',200000,'reason','Manager approved a discretionary personal contribution bonus','reference','Recognition test only','request_id','00000000-0000-4000-8000-000000007777'))->>'id'),false);
select public.test_assert((public.partner_network_reward_create(current_setting('test.partner_a')::uuid,jsonb_build_object('kind','personal','month',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date,'amount',200000,'reason','Manager approved a discretionary personal contribution bonus','reference','Recognition test only','request_id','00000000-0000-4000-8000-000000007777'))->>'id')=current_setting('test.personal_reward'),'same personal reward request cannot double-create after a lost response');
select public.test_error(format('select public.partner_network_reward_create(%L,%L)',current_setting('test.partner_a'),jsonb_build_object('kind','personal','month',date_trunc('month',now() at time zone 'Asia/Ho_Chi_Minh')::date,'amount',200001,'reason','Manager approved a discretionary personal contribution bonus','reference','Recognition test only','request_id','00000000-0000-4000-8000-000000007777')::text),'reward_request_conflict');
select public.test_error(format('select public.partner_network_reward_action(%L,''pay'',%L)',current_setting('test.personal_reward'),jsonb_build_object('amount',200000,'reference','not-approved','paid_at',now())::text),'reward_approval_required');
select public.partner_network_reward_action(current_setting('test.personal_reward')::uuid,'approve','{}');
select public.partner_network_reward_action(current_setting('test.personal_reward')::uuid,'pay',jsonb_build_object('amount',200000,'reference','synthetic-personal-transfer','paid_at',now()));
select public.test_error(format('select public.partner_network_reward_action(%L,''void'',''{"reason":"Cannot remove a recorded payment"}'')',current_setting('test.personal_reward')),'paid_reward_immutable');
-- Tier promotion is explicit, prospective and attributed-revenue gated.
select set_config('test.tier',(public.partner_network_tier_create('{"name":"Senior test","enabled":true,"min_tenure_months":0,"eligibility_mode":"all","first_rate":2,"repeat_rate":2,"monthly_bonus_multiplier":1.5,"reason":"Explicit test policy with tenure eligibility, not a production liability"}')->>'id'),false);
select public.partner_network_apply_classic(current_setting('test.partner_a')::uuid,jsonb_build_object('expected_version',1,'tier_id',current_setting('test.tier'),'reason','Manager explicitly promotes this verified partner prospectively'));
select public.test_assert((select first_rate=2 and repeat_rate=2 and tier_id=current_setting('test.tier')::uuid from public.partner_network_classic_agreements where partner_id=current_setting('test.partner_a')::uuid and version=2),'tier snapshots configured base and repeat rates without stacking');
select public.test_assert((select to_jsonb(c)=current_setting('test.classic_paid')::jsonb from public.partner_network_commissions c where order_id='classic-3'),'promotion never rewrites a paid settlement');
select public.partner_network_tier_state(current_setting('test.tier')::uuid,'{"enabled":false,"reason":"Stop new promotions while retaining existing agreed snapshot"}');
select public.test_assert((select not enabled from public.partner_network_classic_tiers where id=current_setting('test.tier')::uuid),'manager can stop new tier promotions');
select public.test_assert((select first_rate=2 and repeat_rate=2 from public.partner_network_classic_agreements where partner_id=current_setting('test.partner_a')::uuid and version=2),'disabling future promotions does not change the applied agreement');
select set_config('test.impossible_tier',(public.partner_network_tier_create('{"name":"Not yet eligible","enabled":true,"min_collected_12m":999999999999,"eligibility_mode":"all","first_rate":2,"repeat_rate":2,"monthly_bonus_multiplier":2,"reason":"Huge synthetic threshold must not count company-wide sales"}')->>'id'),false);
select public.test_error(format('select public.partner_network_apply_classic(%L,%L)',current_setting('test.partner_a'),jsonb_build_object('expected_version',2,'tier_id',current_setting('test.impossible_tier'),'reason','Attempt to promote without attributed qualifying collections')::text),'classic_tier_not_eligible');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',false);
select public.test_assert(jsonb_array_length(public.partner_network_rewards_snapshot()->'rewards')=0,'other partner cannot see A rewards');
select public.test_error(format('select public.partner_network_rewards_snapshot(%L)',current_setting('test.partner_a')),'own_partner_required');
select public.test_error(format('select public.partner_network_apply_classic(%L,''{"expected_version":0,"reason":"Partner cannot approve own financial terms"}'')',current_setting('test.partner_b')),'manager_required');
select public.test_assert(jsonb_array_length(public.partner_network_rewards_snapshot()->'tiers')=0,'internal promotion thresholds not leaked to unrelated partner');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert(jsonb_array_length(public.partner_network_rewards_snapshot()->'rewards')=2,'own monthly and personal records visible');
select public.test_error($q$select public.partner_network_reward_month('00000000-0000-4000-8000-000000000001',now()::date)$q$,'permission denied');
reset role;
